        "Vormid on ebareeglipärased: ich weiß, du weißt, er/sie/es weiß, wir wissen; lihtminevik wusste, täisminevik hat gewusst. Sageli kasutatakse dass-kõrvallause või küsisõnaga: Ich weiß, dass… / Weißt du, wo…?",
