      "layout": "standardStudy",
      "translation": "vaikne",
      "explanation": [
        "Põhimõte: leise tähendab „vaikne, vaikselt“ – vähe heli või müra: Sei leise! Sprich leise! See iseloomustab häält, muusikat, samme. Vastand on laut.",
        "Võrdlusastmed: leiser (vaiksem), am leisesten. Nimisõna ees saab see lõpu: eine leise Stimme, leise Musik. Sageli kasutatakse määrsõnana: Die Kinder sprechen leise.",
        "Ülekantud tähenduses võib leise tähendada ka „nõrk, kerge“: ein leiser Zweifel – kerge kahtlus."
      ],
      "examples": [
        {
          "de": "Bitte sei leise!",
          "lv": "Palun ole vaikselt!"
        },
        {
          "de": "Die Musik ist zu leise.",
          "lv": "Muusika on liiga vaikne."
        },
        {
          "de": "Sprich bitte leise.",
          "lv": "Räägi palun vaikselt."
        },
        {
          "de": "Das Baby schläft, wir müssen leise sein.",
          "lv": "Beebi magab, me peame vaiksed olema."
        }
      ],
