      "translation": "kui",
      "explanation": [
        "Põhimõte: wenn on alistav sidesõna, mis juhatab sisse tingimus- või korduva tegevuse kõrvallause. Kõrvallauses seisab tegusõna lõpus: Wenn es regnet, bleibe ich zu Hause.",
        "Eesti keeles on see „kui“ — nii tingimuse (wenn du willst) kui ka korduse või tulevase hetke (immer wenn, wenn ich Zeit habe) tähenduses. Kui kõrvallause on esimene, järgneb pealauses tegusõna kohe koma järel.",
        "Ühekordset sündmust minevikus ei väljendata wenn'iga, vaid als'iga: Als ich klein war ... Eesti keeles on mõlemal juhul „kui“, seega tuleb siin olla tähelepanelik."
      ],
      "examples": [
        {
          "de": "Wenn es regnet, bleibe ich zu Hause.",
          "lv": "Kui sajab, jään ma koju."
        },
        {
          "de": "Wenn ich Zeit habe, rufe ich dich an.",
          "lv": "Kui mul on aega, helistan sulle."
        },
        {
          "de": "Immer wenn er kommt, bringt er Blumen.",
          "lv": "Alati, kui ta tuleb, toob ta lilli."
        },
        {
          "de": "Wenn du willst, können wir ins Kino gehen.",
          "lv": "Kui sa tahad, võime kinno minna."
        }
      ],
      "comparison": [
        {
          "word": "als",
          "meaning": "kui (ühekordselt minevikus)",
          "example": "Als ich klein war, wohnte ich in Riga. – Kui ma väike olin, elasin Riias."
        },
        {
          "word": "wann",
          "meaning": "millal (küsimus)",
          "example": "Wann kommst du? – Millal sa tuled?"
        },
        {
          "word": "ob",
          "meaning": "kas",
          "example": "Ich weiß nicht, ob er kommt. – Ma ei tea, kas ta tuleb."
        }
      ],
      "tip": [
        "Pärast Wenn ... lauset on pealauses tegusõna esimene: Wenn es regnet, bleibe ich ...",
        "Tingimuse „kui“ jaoks võib öelda wenn või falls (juhul kui)."
      ],
      "important": [
        "Minevikus ühekordse sündmuse puhul kasutatakse als, mitte wenn.",
        "Wenn ei ole küsisõna; küsimuses „millal?“ kasutatakse wann."
      ],
